ROLES_RENAMED = {"employee": "peer", "supervisor": "peer", "deputy": "manager"}
ROLE_NAME = re.compile(r"[a-z][a-z0-9-]{1,30}")       # as ENTRY_ID: it is a word in the header of each message
ROLE_PROMPT_MAX = 4000
