# The tools of the chat window. see_responsibilities and recall only read, so the owner can ask an agent in chat what
# it is responsible for and what it has learned; a duty is still written by the manager (owner API 1.13) and a memory
# in a task session, never in a chat window.
CHAT_TOOLS = ("read_messages", "tell_owner", "message_owner", "message_agent", "see_responsibilities", "recall",
              "start_task", "request_secret")


def tool_contract(agent, context=None):
    """**A short hash of the tool contract a session of this agent would get now**: every tool's name and its input
    schema, and nothing else.

    A tool's description changes with what the fleet holds — who an agent may write to and what each of them looks
    after, which knowledge files it reads — and those words are built at each `tools/list`, so they reach a session
    the next time it asks. A tool that is new, gone, or that takes other fields does not: the list is served once,
    at `initialize`, and this hub announces no change of it (`listChanged: false`). So this is the part of the list
    that only a new session can learn."""
    shape = sorted((t["name"], json.dumps(t["inputSchema"], sort_keys=True)) for t in tools_for(agent, context))
    return hashlib.sha256(json.dumps(shape).encode()).hexdigest()[:12]


def tools_for(agent, context=None):
    role = agents()[agent].get("role")
    read_only = ("list_my_tasks", "see_team", "see_goals", "see_capacity", "see_triggers", "search_knowledge",
                 "see_responsibilities", "see_earlier_work", "see_history", "recall", "see_standing",
                 "search_history", "read_history", *GOOGLE_READS)
    chat = chat_context(agent, context)
    conversation = conversation_tools(agent, context) if conversation_context(agent, context) else None
    return [{"name": name, "description": described(agent, name, desc), "inputSchema": schema,
             "annotations": {"readOnlyHint": name in read_only, "destructiveHint": False,
                             "idempotentHint": name in read_only, "openWorldHint": False}}
            for r, name, fn, desc, schema in TOOLS if
            role_offers(role, r, name) and
            (name in conversation if conversation is not None else
             name in CHAT_TOOLS if chat else
             not (role in ("worker", "lead") and name in WORKER_CHAT_ONLY) and name not in CONVERSATION_ONLY + CHAT_ONLY) and
            # owner feature secret_requests: a task that a conversation opened, or a part of one, asks him for none
            (name != "request_secret" or not contact_session(agent, context)) and
            # AUTONOMY.md P2: message_contact only once contacts.v2 is on
            (name != "message_contact" or contacts_v2()) and
            # create_login and save_key: off until the owner allows the agent
            (name not in ("create_login", "save_key") or agents()[agent].get("vault_create") is True) and
            # call_api: only for an agent whose machine has the vault broker
            (name != "call_api" or agents()[agent].get("vault") == "broker") and
            # owner feature google: the tools of the agent's levels in team.json now
            (name not in GOOGLE_TOOLS or google_allowed(agent, name))]


def described(agent, name, desc):
    """A tool's description with what this session's agent needs inside it: the Google account that a Google tool
    uses. No description changes at run time (AUTONOMY.md P9.1): the team directory is in the start of every session
    (team_start_text): a task's block, the manager's brief, and an owner chat's first read (chat_team_once)."""
    return google_described(agent, name, desc)


def google_described(agent, name, desc):
    """A Google tool's description names the account that it uses at the start of the session."""
    if name not in GOOGLE_TOOLS:
        return desc
    service = GOOGLE_TOOLS[name][0]
    return f"{desc} It uses the Google {GOOGLE_NAMES[service]} of {google_grant(agent, service)[0]}."


def gate(task_id, name, args):
    """A held task takes only reads. Unknown outcomes block completion and login work until they are checked."""
    hold = active_hold(task_id)
    if hold and name not in ("read_messages", "list_my_tasks"):
        raise ToolError(f"STOP: {tref(task_id)} is {held_word(hold)}. Stop working on it now and wait. "
                        f"A message will say when it resumes.")
    completing = name == "deliver_result" and str(args.get("outcome") or "completed").strip().lower() == "completed"
    if name in ("sign_in", "hand_over", "create_login", "save_key", "call_api", "gmail_send") or completing:
        left = q("SELECT id, title FROM outcomes WHERE task=? AND state='unknown' ORDER BY id", (task_id,))
        # call_api: a request that reads (GET) is a way to check, and the same request_id only asks for its answer.
        if left and name == "call_api" and (args.get("method") == "GET" or q1(
                "SELECT id FROM jobs WHERE task=? AND kind='request' AND request_id=?",
                (task_id, str(args.get("request_id") or "").lower()))):
            left = []
        # gmail_send: the same request_id as an unknown email only gives its text again; it never sends.
        if left and name == "gmail_send" and q1("SELECT id FROM outcomes WHERE task=? AND tool_call_id=?",
                                                (task_id, f"gmail-{str(args.get('request_id') or '').lower()}")):
            left = []
        if left:
            raise ToolError("STOP: first find out whether these earlier actions took effect, without repeating them: " +
                            "; ".join(f"O-{r['id']} {r['title']}" for r in left) + ". Record each finding with resolve_outcome.")


# A field a tool does not take and answers for itself, in words better than the general refusal below:
# see_notes(agent=...) is how one agent tries to read another's notes, and what it has to read back is why it
# cannot, not that the field does not exist.
ANSWERED_FIELDS = {("see_notes", "agent")}


def unknown_fields(name, sent, role=None):
    """The fields of this call that the tool does not take, or none. `sent` is what the caller wrote: the fence
    adds a task_id of its own to tools whose schema has no such field, and that one is not the caller's. A tool with
    an entry for each role (see_history) is read in the caller's role's entry."""
    for r, tname, _fn, _desc, schema in TOOLS:
        if tname == name and (role is None or role_offers(role, r, tname)):
            return sorted(set(sent) - set(schema.get("properties") or {})
                          - {f for n, f in ANSWERED_FIELDS if n == name})
    return []


def task_started(t):
    """The first fleet call of a task's session that the hub carried out marks the task and its attempt started (plan
    P9.4), as list_my_tasks with its task_id does, so that no call is made for that alone. A session whose first prompt
    ended with its task (opening "prompt") has read its start event too: its read would give nothing new, so the
    helper types no signal for it."""
    for e in q("SELECT id, extra FROM events WHERE agent=? AND task=? AND kind='task' AND read_at IS NULL",
               (t["owner"], t["id"])):
        extra = json.loads(e["extra"] or "{}")
        if extra.get("opening") == "prompt" and extra.get("attempt", 1) == t["attempt"]:
            q("UPDATE events SET read_at=? WHERE id=? AND read_at IS NULL", (now(), e["id"]))
    if t["state"] == "submitted":
        q("UPDATE tasks SET state='working', started=COALESCE(started,?) WHERE id=? AND state='submitted'",
          (now(), t["id"]))
    elif not t["started"]:
        q("UPDATE tasks SET started=? WHERE id=?", (now(), t["id"]))
    a = q1("SELECT started FROM attempts WHERE task=? AND attempt=?", (t["id"], t["attempt"]))
    if a and not a["started"]:
        q("UPDATE attempts SET started=? WHERE task=? AND attempt=?", (now(), t["id"], t["attempt"]))


# The fleet calls whose MCP answer carries no unread messages (unread_tail): the read itself, the delivery that closes
# the task, and the two whose answer is JSON that a caller reads.
NO_TAIL = ("read_messages", "deliver_result", "message_agent", "message_owner")


def unread_tail(agent, tid):
    """The messages of a task that its session has not read, read now and added to the MCP answer of another fleet
    call as a block of their own (rpc, plan P9.4), so that the session needs no read_messages for them and its helper
    types no signal. "" when none. A start event alone is not one of them: its read is the session's own, which its
    start tells it to make. It reads in the call's own context (CALL.context), as read_messages does."""
    unread = q1("SELECT 1 FROM events WHERE agent=? AND task=? AND kind='say' AND read_at IS NULL LIMIT 1",
                (agent, tid))
    if not unread:
        return ""
    said = t_read_messages(agent, {"task_id": tref(tid)})
    return "" if said.startswith("No unread messages") else "\n\nNEW MESSAGES of this task, read now:\n" + said


def stale_instructions(name, extra):
    """What an agent reads when it called a tool with a field the tool does not take.

    Almost always the agent is not inventing: it is following words that were written when the tool took that
    field -- its profile, a knowledge file, a task, its own notes. Those words are seeded or the owner's, so no
    release ever corrects them, and the agent has no way to know they are older than the tool. So the refusal
    says which field, where the current contract is, and that what sent it there may be out of date."""
    fields = ", ".join(extra)
    return (f"{name} does not take {fields}. "
            f"{'These fields are' if len(extra) > 1 else 'This field is'} not part of it: the call was refused and "
            f"nothing happened. If you were told to pass {'them' if len(extra) > 1 else 'it'}, those instructions "
            f"are out of date -- a tool's contract changes with the hub, and a profile, a knowledge file or a note "
            f"that restates it does not. This tool's own description is the current contract, and RULES.md says "
            f"what the tool is for. Read the description, call it again with the fields it lists, and report that "
            f"the instructions you followed name a field that is gone.")


def call_tool(agent, name, args, context=None):
    role = agents()[agent].get("role")
    args = dict(args) if isinstance(args, dict) else {}
    sent = dict(args)                   # what the caller wrote, before the fence adds its task_id
    tid, attempt = None, None
    CALL.context = context
    try:
        conversation = conversation_context(agent, context)
        if conversation:
            conv, person = conversation_fence(agent, context)   # a window that the owner closed says STOP, not "no such tool"
        if not any(t["name"] == name for t in tools_for(agent, context)):
            raise ToolError(f"You have no tool named {name}.")
        if conversation and name not in CONVERSATION_WORK_TOOLS and conversation_works(person):
            # AUTONOMY.md P2: in a conversation with the agent's tools, a task tool works for the open conversation
            # task, as in that task's own session: the same fence, gate and record, and a contact drives it
            t = conversation_task(conv["id"])
            if not t:
                raise ToolError("No message of this conversation waits for an answer now, so no task is open here. "
                                "Call read_messages.")
            context = (context[0], tref(t["id"]), str(t["attempt"]))
            CALL.context, conversation = context, False
            args["task_id"] = tref(t["id"])         # the one task of this session, whatever the call named
        if chat_context(agent, context):
            chat_fence(agent, context)
        elif role in ("worker", "lead") and not conversation:
            attempt = context[2] if context else None
            team = role == "lead" and name in LEAD_TEAM_TOOLS      # these name subtasks; the fence is the session's task
            tid = parse_task((None if team else args.get("task_id")) or (context[1] if context else ""))
            t = fence(agent, tid, context)
            attempt = t["attempt"]
            if not team:
                args["task_id"] = tref(tid)
            gate(tid, name, args)
            # task_id is the session's field and not the tool's: every call of a task session is fenced by it,
            # whether or not the tool's own schema lists it (message_agent does not). So it is never the caller's
            # mistake here, and the check below must not read it as one.
            sent.pop("task_id", None)
        # After the fence and the gate, so a held task still reads STOP first, and before anything is done: a call
        # with a field the tool does not take is refused whole, never half-applied with the field dropped.
        extra = unknown_fields(name, sent, role)
        if extra:
            raise ToolError(stale_instructions(name, extra))
        for r, tname, fn, desc, schema in TOOLS:
            if tname == name and role_offers(role, r, name):
                # These wait for an answer, a helper or Google, or read many files (search_knowledge): not under LOCK.
                # deliver_result waits for the helper to send the task's files (deliver_outputs). The history's two
                # take the lock for each step of their own, so the hub answers between the steps of a long search.
                if name in ("ask_my_requester", "sign_in", "hand_over", "create_login", "save_key", "call_api",
                            "message_agent", "search_knowledge", "write_knowledge", "write_skill", "deliver_result",
                            "search_history", "read_history") or \
                        name in GOOGLE_TOOLS:
                    text = fn(agent, args)
                else:
                    with LOCK:
                        if conversation_context(agent, context):
                            conversation_fence(agent, context)
                        elif chat_context(agent, context):
                            chat_fence(agent, context)
                        elif role in ("worker", "lead"):
                            fence(agent, tid, context)
                        text = fn(agent, args)
                log(agent, f"{name} ok")
                # The last gate before any text reaches a session. Each tool that renders stored words masks its
                # own (memory_said, search_knowledge), but a tool that only reads a column masked nothing: a
                # progress note in see_team, an agent's message in read_messages, an agent's notes in see_notes.
                # guard refuses a login that is registered at the moment of the write; this catches the ones
                # registered after it, which is every login the owner added since.
                text = mask_secrets(text)
                if tid:
                    task_started(get_task(tid))         # a refused call leaves no trace, a done one starts the task
                with area("activity"):
                    ins("INSERT INTO calls(ts,agent,task,attempt,name,args,ok,detail) VALUES(?,?,?,?,?,?,1,?)",
                        (now(), agent, tid, attempt, name,
                         "[blocked]" if secret_hit(json.dumps(args)) else json.dumps(args),
                         text[:GOOGLE_CALL_KEEP] if name in GOOGLE_READS else text))
                return text, False
        raise ToolError(f"You have no tool named {name}.")
    except ToolError as e:
        log(agent, f"{name} refused: {e}")
        said = mask_secrets(str(e))
        with area("activity"):
            ins("INSERT INTO calls(ts,agent,task,attempt,name,args,ok,detail) VALUES(?,?,?,?,?,?,0,?)",
                (now(), agent, tid, attempt, name, "[blocked]" if secret_hit(json.dumps(args)) else json.dumps(args),
                 said))
        return said, True
    finally:
        CALL.context = None


# ---------------------------------------------------------------- overview and board

def overview_text():
    out = ["TEAM"]
    for name, a in agents().items():
        row = q1("SELECT * FROM agents WHERE name=?", (name,))
        running = q("SELECT id FROM tasks WHERE owner=? AND state IN ('working','input-required','submitted')", (name,))
        lim = active_limit(name)
        out.append(f"  {name}{'' if agent_active(name) else ' (in setup: no tasks)'}: {a.get('role')}"
                   + (f" ({a['title']})" if a.get("title") else "") + f", {a.get('runtime')} on {a.get('machine')}, can: "
                   f"{', '.join(a.get('can', [])) or '-'}" + (f"; expertise: {', '.join(a['expertise'])}" if a.get("expertise") else "")
                   + f"; helper seen {when(row['last_seen'] if row else None)}; "
                   f"open tasks: {', '.join(tref(r['id']) for r in running) or 'none'}"
                   + (f"; HELD until {clock(lim['until'])}: a session of {limit_source(lim)} on the account they "
                      f"share reached its usage limit" if lim and limit_source(lim) else
                      f"; AT ITS USAGE LIMIT until {clock(lim['until'])}" if lim else ""))
    out.append("")
    out.append("OPEN TASKS")
    rows = q("SELECT * FROM tasks WHERE state NOT IN ('completed','failed','rejected','canceled') ORDER BY id")
    for t in rows:
        note = q1("SELECT text FROM notes WHERE task=? ORDER BY id DESC LIMIT 1", (t["id"],))
        hold = active_hold(t["id"])
        unknown = q1("SELECT COUNT(*) n FROM outcomes WHERE task=? AND state='unknown'", (t["id"],))["n"]
        out.append(f"  {tref(t['id'])} [{t['state']}] {t['title']} -- owner {t['owner']}, last activity "
                   f"{ago(t['last_activity'])} ago" + (f", waiting on {t['waiting_on']}" if t["waiting_on"] else "")
                   + (f"; HELD: {held_word(hold)} ({hold['state']})" if hold else "")
                   + (f"; WAITING until {clock(park['due'])}, as {t['owner']} asked (R-{park['id']}: {park['note']})"
                      if (park := parked(t["id"])) else "")
                   + (f"; waits for {w['recipient']}'s answer to AM-{w['id']}"      # plan C8: a named wait
                      if (w := waits_on_message(t["id"])) else "")
                   + (f"; {unknown} unknown outcome(s)" if unknown else "")
                   + (f"; NO LIVE PATH: {t['stalled_reason']}" if t["stalled_since"] else "")
                   # why this agent got this task: the requester's own reasoning, asked for by create_task and
                   # stored since, and until now printed nowhere an agent could read it
                   + (f"; given to {t['owner']} because: {t['why']}" if t["why"] else "")
                   + step_where(t["step"])          # manager_as_lead: which split piece of work this is a part of
                   + (f"; last note: {note['text']}" if note else ""))
    if not rows:
        out.append("  none")
    out.append("")
    out.append("RESULTS WAITING FOR YOUR CHECK")
    # The manager's own: a lead checks its subtasks in the session of their parent, and check_result refuses the
    # manager any task it did not request, but for a lead that cannot check it any more (lead_left).
    rows = [t for t in q("SELECT * FROM tasks WHERE state IN ('completed','failed','rejected') AND accepted IS NULL "
                         "ORDER BY id")
            if (t["requester"] or manager_name()) == manager_name() or lead_left(t["requester"], t)]
    for t in rows:
        out.append(f"  {tref(t['id'])} [{t['state']}] {t['title']} by {t['owner']}: {t['what']} "
                   f"Output: {t['where_'] or '-'}. Checked: {t['how'] or '-'}")
        for note in q("SELECT agent,ts,text FROM notes WHERE task=? ORDER BY id", (t["id"],)):
            out.append(f"    Progress at {note['ts']} by {note['agent']}: {note['text']}")
    if not rows:
        out.append("  none")
    out.append("")
    out.append("OPEN QUESTIONS")
    # A question of a task that has ended waits for nothing, and stood here for ever.
    rows = q(f"SELECT * FROM questions WHERE answer IS NULL AND task IN (SELECT id FROM tasks WHERE {OPEN_TASK}) "
             f"ORDER BY id")
    for r in rows:
        holder = r["requester"]
        out.append(f"  Q-{r['id']} from {r['asker']} on {tref(r['task'])}, waiting {ago(r['asked'])}"
                   + (f", passed up by {', '.join(question_passers(r))}" if question_passers(r) else "")
                   + (f", with {holder}, which cannot act on it any more: you answer it"
                      if holder not in (None, manager_name()) and lead_left(holder, get_task(r["task"])) else
                      f", asked of {holder}, which answers it" if holder not in (None, manager_name()) else "")
                   + f": {r['text']}" +
                   (f" NOT WAITING: it goes on with \"{r['assumed']}\". Answer only if that is wrong."
                    if r["assumed"] else "") +
                   (" " + access_route(r["asker"], r["access"], holder, r["access_level"],
                                       restarter(get_task(r["task"]))) if r["access"] else ""))
    if not rows:
        out.append("  none")
    out.append("")
    out.append("PERMISSION PROMPTS WAITING")
    rows = q("SELECT p.*, t.requester FROM prompts p LEFT JOIN tasks t ON t.id=p.task WHERE p.decision IS NULL "
             "ORDER BY p.id")
    for r in rows:
        out.append(f"  P-{r['id']} from {r['agent']} on {tref(r['task'])}"
                   + ((f", for {r['requester']} to decide" if not r["task"] or
                       not lead_left(r["requester"], get_task(r["task"])) else
                       f", for {r['requester']}, which cannot decide it any more: you decide it")
                      if r["requester"] not in (None, manager_name()) else "")
                   + f": {r['tool']}: {r['input']}")
    if not rows:
        out.append("  none")
    out.append("")
    # AUTONOMY.md P3: report_up's proposals wait here for the weekly list that the fleet manager takes to the owner
    out.append("PROPOSALS FOR THE OWNER. Decide a weak one yourself with decide_report (noted or wrong); every other one "
               "goes on your weekly list to him, and only his yes makes it goal, with that goal named in note.")
    rows = q("SELECT * FROM reports WHERE kind='proposal' AND decided IS NULL AND collapsed_into IS NULL ORDER BY id")
    out += [report_line(r) for r in rows] or ["  none"]
    out.append("")
    out.append("NEEDS YOU (owner)")
    rows = q("SELECT * FROM needs ORDER BY id")
    for r in rows:
        state = f'answered: "{r["answer"]}"' if r["answer"] is not None else "open"
        out.append(f"  N-{r['id']} {r['title']}" + (f" (for Q-{r['question']})" if r["question"] else "") +
                   f" -- {state}")
    if not rows:
        out.append("  none")
    rows = q("SELECT key, COUNT(*) c FROM outbox GROUP BY key ORDER BY key")
    if rows:
        out.append("")
        out.append("PRACTICE OUTBOX (sends per key)")
        for r in rows:
            out.append(f"  {r['key']}: {r['c']}")
    return "\n".join(out)


def esc(x):
    return html.escape(str(x if x is not None else ""))


