    def ui_resources(self, query):
        """GET /ui/resources (owner feature resource_grants): what a duty can need, as the owner already holds it. Each
        resource with the secrets it uses, the owner's standing for it (grantable up to a level, or kept) and the
        agents that hold it now. No value and no token: a secret is its reference and its name."""
        if not self.ui_allowed():
            return
        generation = kv_get("db_id")
        if query.get("db") != generation:
            return self.json(409, {"error": "hub generation changed; refresh state"})
        with LOCK:
            rev = kit_revision(fresh=True)
            try:
                team, sha, _ = team_view(rev)
            except Refusal as e:
                return self.json(e.status, {"error": str(e)})
            result = dict(resources_view(team), db=generation, revision=rev, sha256=sha)
        return self.json(200, scrub(result), {"Cache-Control": "no-store"})

    def ui_resource(self):
        """POST /ui/resources (owner feature resource_grants): the standing of one resource. policy {"max", "to"} lets
        the manager hand it out up to that level, to any worker or lead ("workers");
        null takes the entry out, so the owner alone gives it. It changes no grant of its own: only who may give this
        resource. There is no second kind of entry: the grant is the authorization."""
        def read(data):
            base = self.integration_base(data, ("resource", "policy"))
            rid, policy = data.get("resource"), data.get("policy")
            if not isinstance(rid, str) or not resource_parts(rid.strip().lower())[0]:
                raise ValueError(f"resource must be <kind>:<what>, with a kind of "
                                 f"{', '.join(sorted(RESOURCE_LEVELS))}")
            if policy is not None and not isinstance(policy, dict):
                raise ValueError('policy must be {"max", "to"}, or null, which takes the entry out')
            return {"base_sha256": base, "resource": rid.strip().lower(), "policy": policy}
        return self.ui_command("resources", read, save_resource)

    def ui_resource_take(self):
        """POST /ui/resources/take (owner feature resource_grants): one agent's hold of one resource ends, whoever gave
        it. Since the grant is the authorization, this one step is the owner's control after a grant, so it needs no
        base: two clicks on two holders never undo each other."""
        def read(data):
            self.only(data, ("resource", "agent"))
            rid, agent = data.get("resource"), data.get("agent")
            if not isinstance(rid, str) or not resource_parts(rid.strip().lower())[0]:
                raise ValueError(f"resource must be <kind>:<what>, with a kind of "
                                 f"{', '.join(sorted(RESOURCE_LEVELS))}")
            if not isinstance(agent, str) or not AGENT_NAME.match(agent):
                raise ValueError("agent must be an agent name")
            return {"resource": rid.strip().lower(), "agent": agent}
        return self.ui_command("resources/take", read, take_resource)

